return ['domain'=>'publishpress-hub','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de-DE','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 12:16+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'Zentralisiertes Verwaltungszentrum für alle PublishPress-Plugins - installieren, aktualisieren und Lizenzen von einem Dashboard aus verwalten.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'Bitte warten Sie, während wir die Komponentenansicht laden...','AI Connections'=>'KI-Verbindungen','Please wait while we load AI connections...'=>'Bitte warten Sie, während wir die KI-Verbindungen laden...','Please wait while we load the plugins dashboard...'=>'Bitte warten Sie, während wir das Dashboard der Plugins laden...','Settings'=>'Einstellungen','Please wait while we load the settings page...'=>'Bitte warten Sie, während wir die Einstellungsseite laden...','You do not have sufficient permissions to access this page.'=>'Sie haben nicht genügend Berechtigungen, um auf diese Seite zuzugreifen.','Welcome'=>'Willkommen','Please wait while we load the welcome page...'=>'Bitte warten Sie, während wir die Willkommensseite laden...','Language pack has not been checked yet.'=>'Das Sprachpaket wurde noch nicht überprüft.','Site locale is English. No language pack is downloaded.'=>'Die Standortlokalisierung ist Englisch. Kein Sprachpaket wurde heruntergeladen.','No language packs are registered.'=>'Es sind keine Sprachpakete registriert.','Language pack directory is not available.'=>'Das Verzeichnis für Sprachpakete ist nicht verfügbar.','Language pack for %1$s (%2$s) matches %3$s.'=>'Das Sprachpaket für %1$s (%2$s) entspricht %3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'Das Sprachpaket für %1$s (%2$s) wurde für %3$s installiert.','Language pack URL was rejected.'=>'Die URL des Sprachpakets wurde abgelehnt.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'Der Download des Sprachpakets für %1$s (%2$s) ist fehlgeschlagen. Das installierte Paket wurde beibehalten.','Language pack could not be unpacked.'=>'Das Sprachpaket konnte nicht entpackt werden.','Language pack is missing a catalog file. The installed pack was left in place.'=>'Das Sprachpaket fehlt eine Katalogdatei. Das installierte Paket wurde beibehalten.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'Das JSON-Katalog des Sprachpakets ist ungültig. Das installierte Paket wurde beibehalten.','Language pack could not be stored. The installed pack was left in place.'=>'Das Sprachpaket konnte nicht gespeichert werden. Das installierte Paket wurde beibehalten.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'Das PHP-Katalog des Sprachpakets konnte nicht erstellt werden. Das installierte Paket wurde beibehalten.','Warning: The license for %1$s has expired. %2$s'=>'Warnung: Die Lizenz für %1$s ist abgelaufen. %2$s','Manage licenses'=>'Lizenzen verwalten','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'Warnung: %1$d Plugin(s) haben abgelaufene Lizenzen: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'Der Lizenzserver hat Ihren Schlüssel akzeptiert, aber diese Seite konnte ihre aktive Lizenz nicht speichern. Bitte kontaktieren Sie den Support und erwähnen Sie diese Nachricht.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'PublishPress-Aktionen für %s. Diese Tools gelten nur für diese Seite. Wenn mehrere Seiten verbunden sind und die angeforderte Seite unklar ist, fragen Sie, welche Seite vor dem Aufrufen eines Tools verwendet werden soll. Bestätigen Sie die Zielseite, bevor Sie die Standortdaten ändern.','WordPress version'=>'WordPress-Version','MCP Adapter version'=>'MCP-Adapterversion','Not active'=>'Nicht aktiv','HTTPS'=>'HTTPS','Available'=>'Verfügbar','Required'=>'Erforderlich','Application passwords'=>'Anwendungskennwörter','Unavailable; check WordPress or security plugin settings'=>'Nicht verfügbar; überprüfen Sie die Einstellungen von WordPress oder Sicherheits-Plugins','Registered actions'=>'Registrierte Aktionen','Selected actions exposed'=>'Ausgewählte Aktionen angezeigt','Changes saved.'=>'Änderungen gespeichert.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'Änderungen gespeichert. Starten Sie Ihre KI-App neu oder aktualisieren Sie die Verbindung zu PublishPress, um die verfügbaren Aktionen zu aktualisieren.','Changes saved. Connect your AI app to continue.'=>'Änderungen gespeichert. Verbinden Sie Ihre KI-App, um fortzufahren.','Changes saved. Select at least one available action to continue.'=>'Änderungen gespeichert. Wählen Sie mindestens eine verfügbare Aktion, um fortzufahren.','Update WordPress to continue'=>'Aktualisieren Sie WordPress, um fortzufahren','WordPress 6.9 or newer is required.'=>'WordPress 6.9 oder neuer ist erforderlich.','Open WordPress updates'=>'WordPress-Updates öffnen','Install the MCP Adapter plugin'=>'Installieren Sie das MCP Adapter-Plugin','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'Installieren Sie das offizielle WordPress MCP Adapter-Plugin, um Ihren KI-Dienst zu verbinden.','Manage plugins'=>'Plugins verwalten','Set up MCP Adapter'=>'MCP Adapter einrichten','Use HTTPS to connect your AI'=>'Verwenden Sie HTTPS, um Ihre KI zu verbinden','Both WordPress and site addresses must use HTTPS.'=>'Sowohl WordPress- als auch Seitenadressen müssen HTTPS verwenden.','Open site settings'=>'Seineneinstellungen öffnen','Add a PublishPress plugin with AI actions'=>'Fügen Sie ein PublishPress-Plugin mit KI-Aktionen hinzu','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'Sie haben noch keine PublishPress-Plugins installiert, die KI-Aktionen unterstützen.','Open PublishPress plugins'=>'PublishPress-Plugins öffnen','Allow application passwords for your account'=>'Anwendungskennwörter für Ihr Konto erlauben','Create an application password in your WordPress profile for assisted or manual setup.'=>'Erstellen Sie ein Anwendungskennwort in Ihrem WordPress-Profil für die unterstützte oder manuelle Einrichtung.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'Anwendungskennwörter sind für Ihr Konto nicht verfügbar. HTTPS- oder Sicherheitseinstellungen des Plugins müssen möglicherweise überprüft werden.','Open application passwords'=>'Anwendungskennwörter öffnen','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'FÜGEN_SIE_IHREN_ANWENDUNGSKENNWORT_HIER_EIN','Ask my AI to help'=>'Bitten Sie meine KI um Hilfe','Recommended. Ask your AI for a setup script to run on your computer.'=>'Empfohlen. Bitten Sie Ihre KI um ein Setup-Skript, das auf Ihrem Computer ausgeführt werden soll.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'Verbinden Sie meine KI-App mit PublishPress. Erstellen Sie ein Setup-Skript und geben Sie mir den genauen Terminalbefehl, um es auszuführen.

1. Bitten Sie mich, meine KI-App und mein Betriebssystem (Windows, macOS oder Linux) auszuwählen. Verwenden Sie interaktive Auswahlmöglichkeiten, wenn verfügbar, andernfalls nummerierte Optionen.
2. Erstellen Sie das Skript mit Ihren Dateiwerkzeugen. Fragen Sie nach der spezifischen Erlaubnis, falls erforderlich. Wenn Sie lokal nicht schreiben können, fügen Sie ein herunterladbares Skript an. Greifen Sie nur auf Code mit Speicheranweisungen zurück, wenn beides nicht möglich ist. Verwenden Sie PowerShell unter Windows und ein entsprechendes Skript unter macOS oder Linux. Hören Sie nicht auf, die Zugriffsbeschränkungen zu erklären oder nur JSON bereitzustellen.
3. Konfigurieren Sie diesen lokalen stdio-Server:
Name: %3$s
Anzeigename: %4$s
Befehl: npx
Argumente: -y @automattic/mcp-wordpress-remote@latest
Umgebung: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Lesen Sie WP_API_PASSWORD über eine versteckte Terminalaufforderung.
Hub-Schreibzugriff: %5$s. Nur individuell ausgewählte Aktionen sind sichtbar.
4. Überprüfen Sie Node.js und npx. Wenn diese fehlen, verlinken Sie zum offiziellen Installer und sagen Sie mir, dass ich das Terminal erneut öffnen soll. Sichern Sie die vorhandenen Einstellungen. Verwenden Sie einen JSON/TOML-Parser oder unterstützte Clientbefehle, um nur diesen Server zu integrieren, wobei andere Einstellungen und Seiten beibehalten werden. Stoppen Sie bei ungültiger Konfiguration oder einem Konflikt bei Endpunkten. Wenn Sie eine alte PublishPress-Desktop-Erweiterung für diese Seite ersetzen, leiten Sie mich an, nur diese Erweiterung zu deaktivieren, um doppelte Verbindungen zu vermeiden. Zitieren Sie Pfade und Werte sicher.
5. Geben Sie kurze Anweisungen zum Ausführen, Neustarten und Genehmigen. Überprüfen Sie die Verbindung oder geben Sie mir eine Aufforderung, um in der App zu testen: Bestätigen Sie die Seiten-URL, listen Sie die tatsächlichen Werkzeuge auf und führen Sie eine schreibgeschützte Abfrage durch. Berichten Sie, ob Schreibwerkzeuge verfügbar sind. Wenn erwartete Schreibwerkzeuge fehlen, bitten Sie mich, die Erlauben von Aktionen, die die Site-Daten ändern, und die ausgewählten Aktionen im Hub zu überprüfen und dann die Verbindung zu aktualisieren. Behaupten Sie keinen Erfolg nur aufgrund der gespeicherten Konfiguration. Testen Sie keine Schreibvorgänge während der Einrichtung. Klären Sie die Zielseite, wenn sie mehrdeutig ist, und fragen Sie vor der Änderung der Site-Daten nach einer Überprüfung.</source>
<t i="30">aktiviert','disabled'=>'deaktiviert','Set up manually'=>'Manuell einrichten','Copy the configuration into your MCP client.'=>'Kopieren Sie die Konfiguration in Ihren MCP-Client.','Actions available through PublishPress Hub.'=>'Aktionen über PublishPress Hub verfügbar.','List WordPress users'=>'WordPress-Benutzer auflisten','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'Benutzer nach Name oder Rolle suchen. Der optionale primitive Berechtigungsfilter überprüft den effektiven Zugriff innerhalb jeder Kandidatenseite. Besuchen Sie alle total_pages, auch wenn eine gefilterte Seite leer ist. Es werden keine E-Mail-Adressen oder Geheimnisse zurückgegeben.','Get WordPress user capabilities'=>'WordPress-Benutzerberechtigungen abrufen','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'Genau eine user_id oder einen Benutzernamen auflösen und deren Identität, Rollen und effektive primitive Berechtigungen zurückgeben. Erraten Sie niemals eine Benutzer-ID. Objekt-spezifische Berechtigungen erfordern eine separate Überprüfung für dieses Objekt.','Find WordPress content'=>'WordPress-Inhalte finden','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'Durchsuchbare Beiträge, Seiten oder einen REST-aktivierten benutzerdefinierten Beitragstyp durchsuchen. Gibt tatsächliche IDs, Titel und Permalinks zurück. Verwenden Sie post_type=page für Seiten. Klären Sie mehrdeutige Titel, bevor Sie eine URL verwenden. Der Standardstatus ist veröffentlicht. Private und Entwurf-Anfragen erzwingen WordPress-Berechtigungen.','List WordPress post types'=>'WordPress-Beitragsarten auflisten','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'Lesbare REST-aktivierte Beitragsarten und die für jeden Typ verwendeten Berechtigungsnamen auflisten. Verwenden Sie diese Namen für Inhaltsabfragen und Berechtigungsfragen.','WordPress'=>'WordPress','Create WordPress user'=>'WordPress-Benutzer erstellen','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'Erstellen Sie ein neues Benutzerkonto mit einem bekannten Benutzernamen, einer E-Mail-Adresse und einer bearbeitbaren Rolle. Fragen Sie nach fehlenden Details. WordPress validiert die Berechtigungen zur Rollenzuweisung. MCP lehnt Administratoren und jede Rolle ab, die Administratorrechte gewährt. Ein Passwort wird privat generiert. Standardmäßig sendet WordPress dem Benutzer einen Link zur Passworteinrichtung per E-Mail. Raten Sie niemals eine E-Mail oder fordern Sie ein Passwort im Chat an.','Create WordPress content'=>'WordPress-Inhalt erstellen','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'Erstellen Sie einen Beitrag, eine Seite oder einen REST-fähigen benutzerdefinierten Beitragstyp. Verwenden Sie post_type=page für Seiten. Standardmäßig wird ein Entwurf erstellt. Veröffentlichen oder planen Sie nur auf Anfrage. WordPress überprüft die Berechtigungen zur Erstellung, Veröffentlichung und Autorenzuweisung. Gibt die tatsächliche ID und den Permalink zurück.','Update WordPress content'=>'WordPress-Inhalt aktualisieren','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'Bearbeiten Sie einen vorhandenen Beitrag, eine Seite oder einen REST-fähigen benutzerdefinierten Beitrag anhand seiner verifizierten ID. Finden Sie zuerst den Inhalt, wenn die ID unbekannt ist. Nur die bereitgestellten Felder werden geändert. WordPress überprüft die Berechtigungen für Objekt, Veröffentlichung und Autorenzuweisung. Es werden keine Löschungen, beliebige Metadaten oder Optionen unterstützt.','Use the exact input types shown in discovery.'=>'Verwenden Sie die genau angezeigten Eingabetypen in der Entdeckung.','You cannot list users.'=>'Sie können keine Benutzer auflisten.','Provide either a user ID or an exact username.'=>'Geben Sie entweder eine Benutzer-ID oder einen genauen Benutzernamen an.','No matching user belongs to this site.'=>'Kein übereinstimmender Benutzer gehört zu dieser Website.','You cannot inspect this user.'=>'Sie können diesen Benutzer nicht inspizieren.','Choose a REST-enabled post type.'=>'Wählen Sie einen REST-fähigen Beitragstyp aus.','This post type does not support content lookup.'=>'Dieser Beitragstyp unterstützt keine Inhaltsabfrage.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'MCP-Tools können keine Benutzer mit Administratorrechten erstellen. Verwenden Sie den Bildschirm "WordPress-Benutzer" für diese Änderung.','Provide at least one content field to update.'=>'Geben Sie mindestens ein Inhaltsfeld zum Aktualisieren an.','Choose an existing REST-enabled post type.'=>'Wählen Sie einen vorhandenen REST-fähigen Beitragstyp aus.','This post type does not support content writes.'=>'Dieser Beitragstyp unterstützt keine Schreibvorgänge für Inhalte.','You cannot perform this operation.'=>'Sie können diese Operation nicht ausführen.','Object must be loaded before initializing.'=>'Das Objekt muss geladen werden, bevor es initialisiert wird.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'Dieser Lizenzschlüssel wird in wp-config.php verwaltet und kann nicht vom Hub aus bearbeitet werden.','No license key found'=>'Kein Lizenzschlüssel gefunden','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'Dieser Lizenzschlüssel wird in wp-config.php verwaltet und kann nicht vom Hub aus deaktiviert werden.','Invalid conflict resolution request.'=>'Ungültige Anfrage zur Konfliktlösung.','The selected plugin is not available for activation.'=>'Das ausgewählte Plugin ist nicht verfügbar zur Aktivierung.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'Die Bereinigung wurde gestoppt, da das ausgewählte Plugin nicht aktiv ist oder die andere Version weiterhin geladen ist. Keine der Kopien wurde gelöscht.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'Das ausgewählte Plugin ist aktiv, aber die andere Version konnte nicht entfernt werden. Bitte entfernen Sie es vom Bildschirm "Plugins".','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'Das ausgewählte Plugin ist nicht mehr aktiv. Bitte aktivieren Sie es erneut vom Bildschirm "Plugins".','No existing license key was found for this plugin.'=>'Es wurde kein vorhandener Lizenzschlüssel für dieses Plugin gefunden.','Database Tables'=>'Datenbanktabellen','PublishPress Plugins'=>'PublishPress-Plugins','PublishPress Hub Debug Log'=>'PublishPress Hub Debug-Log','Debug Log'=>'Debug-Log','The debug log is empty.'=>'Das Debug-Log ist leer.','Version'=>'Version','Debug Mode'=>'Debug-Modus','Enabled'=>'Aktiviert','Disabled'=>'Deaktiviert','Generated At'=>'Erstellt am','Plugins'=>'Plugins','No PublishPress plugins found.'=>'Keine PublishPress-Plugins gefunden.','Tables'=>'Tabellen','No database table information was available.'=>'Es waren keine Datenbanktabelleninformationen verfügbar.','Size'=>'Größe','Engine'=>'Engine','Rows'=>'Zeilen','Collation'=>'Sortierung','Charset'=>'Zeichensatz','Total Database Size'=>'Gesamte Datenbankgröße','Not installed'=>'Nicht installiert','Active'=>'Aktiv','Inactive'=>'Inaktiv','unknown'=>'unbekannt','License'=>'Lizenz','Free plugin not set for plugin family: %s'=>'Kostenloses Plugin wurde für die Plugin-Familie nicht festgelegt: %s','Pro plugin not set for plugin family: %s'=>'Pro-Plugin wurde für die Plugin-Familie nicht festgelegt: %s','License activation error. Please try again later or contact support for help.'=>'Lizenzaktivierungsfehler. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','License deactivation error. Please try again later or contact support for help.'=>'Lizenzdeaktivierungsfehler. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','This license is currently disabled. Please contact support for help.'=>'Diese Lizenz ist derzeit deaktiviert. Bitte wenden Sie sich an den Support um Hilfe.','This license has expired. Please contact support to renew it.'=>'Diese Lizenz ist abgelaufen. Bitte wenden Sie sich an den Support um sie zu erneuern.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'Dieser Lizenzschlüssel konnte nicht aktiviert werden. Er könnte ungültig, blockiert oder für dieses Plugin nicht autorisiert sein. Bitte überprüfen Sie den Schlüssel und wenden Sie sich an den PublishPress-Support, wenn das Problem weiterhin besteht.','This license cannot be used for this plugin. Please contact support for help.'=>'Diese Lizenz kann nicht für dieses Plugin verwendet werden. Bitte wenden Sie sich an den Support um Hilfe.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'Diese Lizenz stimmt nicht mit dem Plugin überein, das Sie aktivieren möchten. Bitte wenden Sie sich an den Support um Hilfe.','License key does not match our records. Please contact support for assistance.'=>'Lizenzschlüssel stimmt nicht mit unseren Aufzeichnungen überein. Bitte wenden Sie sich an den Support um Hilfe.','No license key provided. Please enter a valid license key.'=>'Kein Lizenzschlüssel angegeben. Bitte geben Sie einen gültigen Lizenzschlüssel ein.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'Ihre Seiten-URL ist erforderlich, um die Lizenz zu aktivieren. Bitte geben Sie eine gültige Seiten-URL ein, um fortzufahren.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'Lizenzaktivierungsgrenze erreicht. Bitte wenden Sie sich an den Support, um ein Upgrade durchzuführen oder auf einer anderen Seite zu deaktivieren.','This license cannot be activated. Please contact support for help.'=>'Diese Lizenz kann nicht aktiviert werden. Bitte wenden Sie sich an den Support um Hilfe.','License server error. Please try again later or contact support for help.'=>'Lizenzserverfehler. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','The license server returned an invalid response. Please try again later or contact support for help.'=>'Der Lizenzserver hat eine ungültige Antwort zurückgegeben. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','This license is inactive for this site. Please contact support for help.'=>'Diese Lizenz ist für diese Seite inaktiv. Bitte wenden Sie sich an den Support um Hilfe.','Plugin activation failed. Please try again later or contact support for help.'=>'Plugin-Aktivierung fehlgeschlagen. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','This action is not possible because the plugin is already installed.'=>'Diese Aktion ist nicht möglich, da das Plugin bereits installiert ist.','Plugin deactivation failed. Please try again later or contact support for help.'=>'Plugin-Deaktivierung fehlgeschlagen. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','Plugin family not found. Please contact support for help.'=>'Plugin-Familie nicht gefunden. Bitte wenden Sie sich an den Support um Hilfe.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'Diese Aktion ist nicht möglich, da sowohl die kostenlose als auch die Pro-Version installiert sind. Bitte deinstallieren Sie eine Version, um fortzufahren.','Plugin installation failed. Please contact support for help.'=>'Plugin-Installation fehlgeschlagen. Bitte wenden Sie sich an den Support um Hilfe.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'Diese Aktion ist nicht möglich, da das Plugin nicht aktiviert ist. Bitte aktivieren Sie das Plugin und versuchen Sie es erneut.','Plugin not found in our available plugins list. Please contact support for help.'=>'Plugin nicht in unserer Liste verfügbarer Plugins gefunden. Bitte wenden Sie sich an den Support um Hilfe.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'Diese Aktion ist nicht möglich, da das Plugin nicht installiert ist. Bitte installieren Sie das Plugin und versuchen Sie es erneut.','Unknown license server error. Please try again later or contact support for help.'=>'Unbekannter Lizenzserverfehler. Bitte versuchen Sie es später erneut oder wenden Sie sich an den Support um Hilfe.','Sell digital products, programs, and services from your website.'=>'Verkaufen Sie digitale Produkte, Programme und Dienstleistungen von Ihrer Website.','Create and manage tags, categories, and taxonomy terms.'=>'Erstellen und verwalten Sie Tags, Kategorien und Taxonomiebegriffe.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'Organisieren Sie Taxonomiebegriffe in Gruppen und zeigen Sie sie in Wolken, Tabs und Listen an.','Define tasks that authors must complete before publishing.'=>'Definieren Sie Aufgaben, die Autoren vor der Veröffentlichung abschließen müssen.','Control who can edit and view your content.'=>'Steuern Sie, wer Ihren Inhalt bearbeiten und ansehen kann.','Create, manage and display authors for your content.'=>'Erstellen, verwalten und zeigen Sie Autoren für Ihren Inhalt an.','All the tools you need to improve the block editor.'=>'Alle Werkzeuge, die Sie benötigen, um den Block-Editor zu verbessern.','Control your admin area and user roles.'=>'Steuern Sie Ihren Admin-Bereich und Benutzerrollen.','Schedule changes to your posts.'=>'Planen Sie Änderungen an Ihren Beiträgen.','Organize, schedule, and plan your publishing.'=>'Organisieren, planen und planen Sie Ihre Veröffentlichung.','Approve and schedule new versions to your published posts.'=>'Genehmigen und planen Sie neue Versionen Ihrer veröffentlichten Beiträge.','Organize your posts into issues or series.'=>'Organisieren Sie Ihre Beiträge in Ausgaben oder Serien.','Create custom URLs for your posts and external links.'=>'Erstellen Sie benutzerdefinierte URLs für Ihre Beiträge und externen Links.','Create custom statuses and publishing workflows.'=>'Erstellen Sie benutzerdefinierte Status und Veröffentlichungs-Workflows.','Dependency "%s" not found in container.'=>'Abhängigkeit "%s" im Container nicht gefunden.','Error validating license: %s'=>'Fehler bei der Lizenzvalidierung: %s','Error getting license info: %s'=>'Fehler beim Abrufen der Lizenzinformationen: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'Der Lizenzserver hat diese Anfrage abgelehnt. Dies kann passieren, wenn ein Lizenzschlüssel oder eine Site blockiert wurde. Bitte kontaktieren Sie den PublishPress-Support für Hilfe.','Too many requests. Please try again later.'=>'Zu viele Anfragen. Bitte versuchen Sie es später erneut.','An error occurred while processing your request.'=>'Ein Fehler ist beim Verarbeiten Ihrer Anfrage aufgetreten.','Template not found: %s'=>'Vorlage nicht gefunden: %s','Path cannot be empty'=>'Pfad darf nicht leer sein','File extension cannot be empty'=>'Dateierweiterung darf nicht leer sein','Invalid file path: null byte detected'=>'Ungültiger Dateipfad: Null-Byte erkannt','Invalid file path: directory traversal detected'=>'Ungültiger Dateipfad: Verzeichnisdurchquerung erkannt','Invalid file path: parent directory does not exist: %s'=>'Ungültiger Dateipfad: Übergeordnetes Verzeichnis existiert nicht: %s','Invalid file path: unable to resolve path'=>'Ungültiger Dateipfad: Pfad kann nicht aufgelöst werden','Invalid file path: operation not allowed outside permitted directories'=>'Ungültiger Dateipfad: Operation außerhalb der erlaubten Verzeichnisse nicht erlaubt','Download URL failed WordPress validation'=>'Download-URL hat die WordPress-Validierung nicht bestanden','Downloaded plugin file does not exist'=>'Heruntergeladene Plugin-Datei existiert nicht','Downloaded plugin file is empty'=>'Heruntergeladene Plugin-Datei ist leer','Cannot read downloaded plugin file'=>'Kann heruntergeladene Plugin-Datei nicht lesen','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'Heruntergeladene Datei ist kein gültiges ZIP-Archiv. Die Download-URL könnte eine Fehlerseite zurückgeben.','Failed to unzip plugin file: %s'=>'Fehler beim Entpacken der Plugin-Datei: %s','Failed to unzip plugin file'=>'Fehler beim Entpacken der Plugin-Datei','Failed to activate plugin: %s'=>'Fehler beim Aktivieren des Plugins: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'Konflikte für netzwerkaktive Plugins aus dem Netzwerk-Admin lösen.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'Aktivierungswiederherstellung fehlgeschlagen. Beide Plugin-Kopien wurden beibehalten. Bitte stellen Sie die vorherige Version vom Plugins-Bildschirm wieder her.','The other plugin could not be deactivated.'=>'Das andere Plugin konnte nicht deaktiviert werden.','The selected plugin did not remain active.'=>'Das ausgewählte Plugin blieb nicht aktiv.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'Das ausgewählte Plugin konnte nicht aktiviert werden. Weder wurde eine Kopie gelöscht, noch wurden die vorherigen Aktivierungseinstellungen wiederhergestellt.','Failed to delete plugin: %s'=>'Fehler beim Löschen des Plugins: %s','No update available for this plugin'=>'Kein Update für dieses Plugin verfügbar','Invalid update information for this plugin'=>'Ungültige Updateinformationen für dieses Plugin','Update package not available'=>'Updatepaket nicht verfügbar','Failed to update plugin: %s'=>'Fehler beim Aktualisieren des Plugins: %s','Plugin update failed'=>'Plugin-Aktualisierung fehlgeschlagen','Invalid download URL provided'=>'Ungültige Download-URL angegeben','Download URL must use HTTP or HTTPS protocol'=>'Download-URL muss das HTTP- oder HTTPS-Protokoll verwenden','Download URL is not from an allowed domain: %s'=>'Download-URL stammt nicht von einer erlaubten Domain: %s','Could not create a temporary package file'=>'Konnte keine temporäre Paketdatei erstellen','Failed to download plugin: %s'=>'Fehler beim Herunterladen des Plugins: %s','The plugin package download failed'=>'Der Download des Plugin-Pakets ist fehlgeschlagen','Failed to get plugin information: %s'=>'Fehler beim Abrufen der Plugin-Informationen: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'MCP-Adapter konnte nicht installiert oder aktiviert werden. Verwenden Sie die Plugin-Seite oder kontaktieren Sie Ihren Host.','MCP Adapter activated.'=>'MCP-Adapter aktiviert.','Filter'=>'Filter','ERR'=>'ERR','.'=>'.']];